ga8J(){return"\u062a\u0639\u0630\u0651\u0631 \u062a\u062d\u0645\u064a\u0644 \u0627\u0644\u0645\u0632\u0627\u062f. \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644\u0643 \u0648\u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629."},
ga8O(){return"\u0647\u0630\u0627 \u0644\u0627\u0639\u0628\u0643\u060c \u0648\u0623\u0646\u062a \u062a\u062a\u0627\u0628\u0639 \u0627\u0644\u0645\u0632\u0627\u062f \u0627\u0644\u0630\u064a \u0641\u062a\u062d\u0647 \u0648\u0643\u064a\u0644\u0647. \u062a\u0638\u0647\u0631 \u0627\u0644\u0639\u0631\u0648\u0636 \u0647\u0646\u0627 \u0641\u0648\u0631 \u0648\u0635\u0648\u0644\u0647\u0627\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646\u0643 \u062a\u0642\u062f\u064a\u0645 \u0639\u0631\u0636 \u0639\u0644\u0649 \u0644\u0627\u0639\u0628\u0643."},
ga8p(){return"\u0644\u0645 \u064a\u064f\u0642\u0628\u0644 \u0627\u0644\u0639\u0631\u0636\u060c \u0641\u0642\u062f \u064a\u0643\u0648\u0646 \u0627\u0644\u0633\u0648\u0642 \u0642\u062f \u062a\u062d\u062f\u0651\u062b."},
gGW(){return"\u0641\u0634\u0644 \u0627\u0644\u0634\u0631\u0627\u0621."},
ga8F(){return"\u0641\u064a \u0645\u0632\u0627\u062f \u0627\u0644\u0648\u0643\u0627\u0644\u0629 \u064a\u0641\u0648\u0632 \u0623\u0639\u0644\u0649 \u0639\u0631\u0636. \u064a\u0645\u0643\u0646\u0643 \u0631\u0641\u0639 \u0639\u0631\u0636\u0643\u060c \u0648\u0625\u0630\u0627 \u062a\u062c\u0627\u0648\u0632\u0643 \u0623\u062d\u062f \u0641\u0633\u064a\u0635\u0644\u0643 \u0625\u0634\u0639\u0627\u0631."},
ga8G(){return"\u0627\u0644\u0634\u0631\u0627\u0621 \u0627\u0644\u0641\u0648\u0631\u064a \u064a\u063a\u0644\u0642 \u0627\u0644\u0645\u0632\u0627\u062f \u0641\u064a \u0627\u0644\u062d\u0627\u0644: \u062a\u0633\u0642\u0637 \u0627\u0644\u0639\u0631\u0648\u0636 \u0627\u0644\u0623\u062e\u0631\u0649 \u0648\u064a\u0646\u062a\u0642\u0644 \u0627\u0644\u0644\u0627\u0639\u0628 \u0625\u0644\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629."},
ga8H(){return"\u064a\u0628\u0642\u0649 \u0627\u0644\u0644\u0627\u0639\u0628 \u0644\u062f\u0649 \u0627\u0644\u0628\u0627\u0626\u0639 \u0637\u0648\u0627\u0644 \u0627\u0644\u0645\u0632\u0627\u062f. \u0648\u0625\u0630\u0627 \u0627\u0646\u062a\u0647\u0649 \u0627\u0644\u0648\u0642\u062a \u062f\u0648\u0646 \u0623\u064a \u0639\u0631\u0636\u060c \u064a\u064f\u063a\u0644\u0642 \u0627\u0644\u0625\u0639\u0644\u0627\u0646 \u062f\u0648\u0646 \u0628\u064a\u0639."},
