ga8E(){return"\u064a\u0641\u0648\u0632 \u0623\u0639\u0644\u0649 \u0639\u0631\u0636"},
gGZ(){return"\u0623\u062d\u062f\u062b \u0627\u0644\u0639\u0631\u0648\u0636"},
ga8x(){return"\u0623\u064f\u063a\u0644\u0642 \u0627\u0644\u0645\u0632\u0627\u062f. \u0627\u0646\u062a\u0647\u0649 \u0627\u0644\u0648\u0642\u062a \u062f\u0648\u0646 \u0628\u064a\u0639\u060c \u0648\u0644\u0645 \u064a\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u0644\u0627\u0646 \u064a\u0633\u062a\u0642\u0628\u0644 \u0639\u0631\u0648\u0636\u064b\u0627."},
ga8y(){return"\u0623\u064f\u063a\u0644\u0642 \u0627\u0644\u0645\u0632\u0627\u062f. \u0627\u0646\u062a\u0642\u0644 \u0627\u0644\u0644\u0627\u0639\u0628 \u0625\u0644\u0649 \u0646\u0627\u062f\u064a\u0643\u060c \u0648\u0644\u0645 \u064a\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u0644\u0627\u0646 \u064a\u0633\u062a\u0642\u0628\u0644 \u0639\u0631\u0648\u0636\u064b\u0627."},
ga8w(){return"\u0623\u064f\u063a\u0644\u0642 \u0627\u0644\u0645\u0632\u0627\u062f. \u0627\u062a\u0641\u0642 \u0627\u0644\u0644\u0627\u0639\u0628 \u0645\u0639 \u0646\u0627\u062f\u064d \u0622\u062e\u0631\u060c \u0648\u0644\u0645 \u064a\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u0644\u0627\u0646 \u064a\u0633\u062a\u0642\u0628\u0644 \u0639\u0631\u0648\u0636\u064b\u0627."},
ga8R(){return"\u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d"},
ga8D(){return"\u0627\u0644\u0623\u0639\u0644\u0649"},
gp0(){return"\u0627\u0634\u062a\u0631\u0650 \u0627\u0644\u0622\u0646"},
ga8U(){return"\u0623\u0631\u0633\u0644 \u0639\u0631\u0636\u0643"},
ga8W(){return"\u064a\u064f\u063a\u0644\u0642 \u0641\u0648\u0631\u064b\u0627"},
