gabS(){return"\u0627\u0644\u0639\u0648\u062f\u0629"},
gabK(){return"\u0627\u0644\u0643\u0634\u0651\u0627\u0641 \u0647\u0648 \u0627\u0644\u0637\u0631\u064a\u0642 \u0627\u0644\u0648\u062d\u064a\u062f \u0644\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0627\u0644\u0644\u0627\u0639\u0628\u064a\u0646 \u0628\u0644\u0627 \u0623\u0646\u062f\u064a\u0629. \u062a\u062d\u062f\u062f \u0627\u0644\u0645\u0647\u0645\u0629: \u0623\u064a \u0645\u0631\u0643\u0632\u060c \u0648\u0623\u064a \u0645\u0646\u0637\u0642\u0629\u060c \u0648\u0623\u064a \u0646\u0648\u0639 \u0645\u0646 \u0627\u0644\u0644\u0627\u0639\u0628\u064a\u0646\u060c \u0648\u0643\u0645 \u064a\u0648\u0645\u064b\u0627."},
gabL(){return"\u0627\u0644\u062a\u0643\u0644\u0641\u0629 \u062a\u064f\u062f\u0641\u0639 \u0645\u0642\u062f\u0645\u064b\u0627\u060c \u0648\u0642\u062f \u064a\u0639\u0648\u062f \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0641\u0627\u0631\u063a\u064b\u0627. \u0639\u062f\u062f \u0627\u0644\u0645\u0647\u0627\u0645 \u0627\u0644\u062a\u064a \u062a\u0641\u062a\u062d\u0647\u0627 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647 \u064a\u062d\u062f\u062f\u0647 \u0639\u062f\u062f \u0627\u0644\u0643\u0634\u0651\u0627\u0641\u064a\u0646 \u0627\u0644\u0645\u062a\u0639\u0627\u0642\u062f \u0645\u0639\u0647\u0645."},
gabM(){return"\u0645\u0631\u0634\u062d \u0627\u0644\u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0644\u0627 \u064a\u062d\u0645\u0644 \u0631\u0633\u0648\u0645 \u0627\u0646\u062a\u0642\u0627\u0644\u060c \u0648\u0627\u0644\u0645\u0637\u0631\u0648\u062d \u0644\u0644\u062a\u0641\u0627\u0648\u0636 \u0647\u0648 \u0627\u0644\u0631\u0627\u062a\u0628 \u0627\u0644\u0633\u0646\u0648\u064a \u0641\u0642\u0637."},
gabJ(){return"\u062a\u064f\u062f\u0641\u0639 \u0645\u0642\u062f\u0645\u064b\u0627"},
gabI(){return"\u0627\u0644\u0639\u062f\u0633\u0629"},
gabN(){return"\u0644\u0627 \u064a\u0648\u062c\u062f"},
gabR(){return"\u0639\u0627\u062f \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0641\u0627\u0631\u063a\u064b\u0627"},
gabG(){return"\u0623\u064a \u0645\u0631\u0643\u0632"},
gyY(){return"\u0645\u0648\u0647\u0628\u0629 \u0634\u0627\u0628\u0629"},
gyW(){return"\u0627\u0644\u0642\u0627\u0631\u0629"},
gI2(){return"\u062d\u0648\u0644 \u0627\u0644\u0639\u0627\u0644\u0645"},
gamb(){return"\u062a\u0639\u0630\u0631 \u062a\u062d\u0645\u064a\u0644 \u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629. \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644\u0643 \u0648\u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u064b\u0627."},
gamd(){return"\u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629 \u0645\u0642\u0641\u0644\u0629 \u2014 \u0644\u0645 \u064a\u064f\u062d\u0641\u0638 \u0627\u0644\u062a\u063a\u064a\u064a\u0631"},
