gamP(){return"\u0627\u0644\u0623\u062f\u0648\u0627\u0631 \u062a\u064f\u0645\u0646\u062d \u0644\u0644\u0627\u0639\u0628\u064a \u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0641\u0642\u0637"},
gzK(){return"\u062f\u0643\u0629 \u0627\u0644\u0628\u062f\u0644\u0627\u0621 \u0645\u0645\u062a\u0644\u0626\u0629"},
gzP(){return"\u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0629 \u0648\u0627\u0644\u062e\u0637\u0629"},
gam5(){return"\u064a\u0628\u0642\u0649 \u0627\u0644\u0645\u0644\u0639\u0628 \u0628\u0627\u0644\u062d\u062c\u0645 \u0646\u0641\u0633\u0647 \u0641\u064a \u0643\u0644 \u062a\u0628\u0648\u064a\u0628\u060c \u0648\u0627\u0644\u0644\u0648\u062d\u0629 \u0627\u0644\u0633\u0641\u0644\u064a\u0629 \u062a\u062a\u0645\u0631\u0631 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u0644. \u0644\u0645\u0633\u0629 \u0648\u0627\u062d\u062f\u0629 \u062a\u0639\u0631\u0636 \u0627\u0644\u0644\u0627\u0639\u0628\u060c \u0648\u0627\u0644\u0636\u063a\u0637 \u0627\u0644\u0645\u0637\u0648\u0644 \u0645\u0639 \u0627\u0644\u0633\u062d\u0628 \u064a\u0646\u0642\u0644\u0647 \u0625\u0644\u0649 \u0645\u0643\u0627\u0646 \u0622\u062e\u0631."},
