gyu(){return"\u064a\u062a\u062f\u0631\u0628 \u0627\u0644\u0641\u0631\u064a\u0642 \u0647\u0646\u0627 \u0643\u0644 \u0635\u0628\u0627\u062d. \u0643\u0644\u0645\u0627 \u0643\u0628\u0631\u062a \u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u062a\u0637\u0648\u0631 \u0627\u0644\u0644\u0627\u0639\u0628\u0648\u0646 \u0623\u0633\u0631\u0639\u060c \u0648\u062a\u0639\u0627\u0641\u0648\u0627 \u0623\u0633\u0631\u0639 \u0628\u0639\u062f \u0627\u0644\u0645\u0628\u0627\u0631\u064a\u0627\u062a\u060c \u0648\u062a\u0639\u0631\u0636\u0648\u0627 \u0644\u0625\u0635\u0627\u0628\u0627\u062a \u0623\u0642\u0644."},
gGP(){return"\u062a\u0643\u0628\u0631 \u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u0645\u0631\u062d\u0644\u0629 \u0648\u0627\u062d\u062f\u0629: \u062a\u0637\u0648\u0631 \u0623\u0633\u0631\u0639\u060c \u0648\u062a\u0639\u0627\u0641\u064d \u0623\u0633\u0631\u0639\u060c \u0648\u0645\u0644\u0627\u0639\u0628 \u0623\u0643\u062b\u0631. \u0644\u0627 \u064a\u062a\u063a\u064a\u0631 \u0627\u0644\u0623\u062b\u0631 \u062d\u062a\u0649 \u064a\u0646\u062a\u0647\u064a \u0627\u0644\u0628\u0646\u0627\u0621."},
gGS(){return"\u062a\u064f\u062c\u062f\u064e\u0651\u062f \u0627\u0644\u0645\u0644\u0627\u0639\u0628 \u0648\u0627\u0644\u0635\u0627\u0644\u0627\u062a\u060c \u0648\u062a\u0639\u0645\u0644 \u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u0628\u0643\u0627\u0645\u0644 \u0643\u0641\u0627\u0621\u062a\u0647\u0627 \u0645\u0646 \u062c\u062f\u064a\u062f."},
GT(a){return"\u0627\u0644\u0631\u0627\u0641\u0639\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0648\u0642\u0639. \u064a\u062a\u0628\u0642\u0649 "+a+" \u0639\u0644\u0649 \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d\u060c \u0648\u0644\u0627 \u062a\u062a\u0648\u0642\u0641 \u0627\u0644\u062a\u062f\u0631\u064a\u0628\u0627\u062a \u062e\u0644\u0627\u0644 \u0630\u0644\u0643."},
gGU(){return"\u0627\u0644\u0631\u0627\u0641\u0639\u0627\u062a \u0641\u064a \u0627\u0644\u0645\u0648\u0642\u0639. \u0644\u0627 \u062a\u062a\u0648\u0642\u0641 \u0627\u0644\u062a\u062f\u0631\u064a\u0628\u0627\u062a \u062d\u062a\u0649 \u0627\u0644\u0627\u0641\u062a\u062a\u0627\u062d."},
gyr(){return"\u0645\u0646 \u0623\u0641\u0636\u0644 \u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u062a\u062f\u0631\u064a\u0628 \u0641\u064a \u0627\u0644\u0628\u0644\u0627\u062f"},
gyq(){return"\u0644\u0645 \u062a\u0639\u062f \u0647\u0646\u0627\u0643 \u0645\u0631\u062d\u0644\u0629 \u0644\u0644\u062a\u0637\u0648\u064a\u0631. \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0627\u0644\u0622\u0646 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0634\u0623\u0629 \u0641\u064a \u062d\u0627\u0644\u0629 \u062c\u064a\u062f\u0629."},
