gEE(){return"\u062a\u0645 \u062a\u062d\u062f\u064a\u062b \u0633\u0639\u0631 \u0627\u0644\u062a\u0630\u0643\u0631\u0629"},
gEM(){return"\u0627\u0644\u0645\u062f\u0631\u062c\u0627\u062a \u0645\u0645\u062a\u0644\u0626\u0629."},
