a0J(a){return"\u0627\u0646\u0636\u0645 \u0625\u0644\u064a\u0646\u0627: **"+a+"**. \u0623\u0628\u0642\u064a\u062a \u0627\u0644\u0633\u0642\u0641 \u0645\u062d\u0643\u0645\u064b\u0627\u060c \u0648\u0623\u062d\u0636\u0631\u0647 \u0627\u0644\u0645\u062f\u064a\u0631 \u0628\u0633\u0639\u0631 \u0631\u062e\u064a\u0635."},
a0K(a,b){return"\u0627\u0646\u0636\u0645 \u0625\u0644\u064a\u0646\u0627: **"+a+"**. \u062c\u0639\u0644\u062a \u0627\u0644\u0633\u0642\u0641 \u0648\u0627\u0633\u0639\u064b\u0627\u061b \u0648\u0643\u0627\u0646 \u0627\u0644\u0628\u0627\u0626\u0639 \u0633\u064a\u0646\u0632\u0644 \u0625\u0644\u0649 "+b+"."},
ga26(){return"\u062a\u0633\u0644\u0651\u0645 \u0644\u0627\u0639\u0628\u0643 \u0627\u0644\u0641\u0627\u0626\u0636 \u0625\u0644\u0649 \u0648\u0643\u0627\u0644\u0629. \u062a\u0635\u0644 \u0627\u0644\u0648\u0643\u0627\u0644\u0627\u062a \u0625\u0644\u0649 \u0623\u0646\u062f\u064a\u0629 \u0645\u062e\u062a\u0644\u0641\u0629\u061b \u0648\u062a\u064f\u0638\u0647\u0631 \u0643\u0644 \u0628\u0637\u0627\u0642\u0629 **\u0645\u0627 \u062a\u062d\u0635\u0644 \u0639\u0644\u064a\u0647 \u0625\u0646 \u0628\u064a\u0639**. \u0627\u062e\u062a\u0631 \u0648\u0627\u062d\u062f\u0629 \u0648**\u0627\u0639\u0631\u0636\u0647 \u0644\u0644\u0628\u064a\u0639**."},
ga29(){return"\u0623\u0643\u0651\u062f: \u0628\u0639\u062f \u0641\u062a\u062d \u0627\u0644\u0639\u0631\u0636 \u0644\u0627 \u064a\u0645\u0643\u0646 \u0633\u062d\u0628\u0647."},
a2a(a){return"\u0641\u064f\u062a\u062d \u0627\u0644\u0639\u0631\u0636. **"+a+"**."},
ga27(){return"\u0633\u064f\u0631\u0651\u0639 \u0627\u0644\u0648\u0642\u062a. \u0643\u0644\u0645\u0627 \u0648\u0635\u0644\u062a \u0627\u0644\u0639\u0631\u0648\u0636 \u0627\u0631\u062a\u0641\u0639 \u0623\u0639\u0644\u0649 \u0631\u0642\u0645."},
a2b(a,b,c){return"\u0641\u0627\u0632 **"+a+"**: **"+b+"**. \u0648\u0635\u0644\u062a "+c+" \u0625\u0644\u0649 \u0627\u0644\u0623\u0646\u062f\u064a\u0629 \u0627\u0644\u0643\u0628\u0631\u0649 \u0641\u0627\u0631\u062a\u0641\u0639 \u0627\u0644\u0633\u0639\u0631. \u062a\u0623\u062e\u0630 \u0627\u0644\u0648\u0643\u0627\u0644\u0629 \u062d\u0635\u062a\u0647\u0627\u060c \u0648\u0627\u0644\u0628\u0627\u0642\u064a \u0644\u062e\u0632\u064a\u0646\u062a\u0643."},
a2c(a,b,c,d,e){return"\u0641\u0627\u0632 **"+a+"**: **"+b+"**. \u0644\u0627 \u062a\u0635\u0644 "+c+" \u0625\u0644\u0649 \u0627\u0644\u0623\u0646\u062f\u064a\u0629 \u0627\u0644\u0643\u0628\u0631\u0649\u061b \u0648\u0645\u0639 "+d+" \u0643\u0627\u0646 \u0623\u0639\u0644\u0649 \u0639\u0631\u0636 \u0633\u064a\u0628\u0644\u063a "+e+". \u062a\u0623\u062e\u0630 \u0627\u0644\u0648\u0643\u0627\u0644\u0629 \u062d\u0635\u062a\u0647\u0627\u060c \u0648\u0627\u0644\u0628\u0627\u0642\u064a \u0644\u062e\u0632\u064a\u0646\u062a\u0643."},
ga28(){return"\u0623\u064f\u063a\u0644\u0642 \u0627\u0644\u0628\u064a\u0639. \u0641\u064a \u0647\u0630\u0647 \u0627\u0644\u0623\u062b\u0646\u0627\u0621 \u064a\u062a\u0635\u0644 \u0628\u0643 \u0645\u062f\u064a\u0631 \u0627\u0644\u0643\u0631\u0629\u2026"},
